//! Live tiles: one region each, generated by an arnis process into a staging copy of the
//! One World, so a failing tile cannot take the session down.

use crate::args::Args;
use crate::coordinate_system::cartesian::XZBBox;
use crate::coordinate_system::geographic::LLBBox;
use crate::world_utils::WorldLayout;
use clap::ValueEnum;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, Mutex};
use std::time::Instant;

pub const LIVE_DIR: &str = "arnis_one_world/live";
/// A tile still running after this is stuck, and is stopped and tried again.
const TILE_DEADLINE: std::time::Duration = std::time::Duration::from_secs(600);
/// Map ids each staging world may hand out in one session.
const MAP_IDS_PER_WORKER: i32 = 200_000;

fn value_name<T: ValueEnum>(v: &T) -> String {
    v.to_possible_value()
        .map(|p| p.get_name().to_string())
        .unwrap_or_default()
}

/// The generation settings of `args` as flags for a tile run. World-level settings
/// (game mode, time, spawn) belong to the world's first area and are left out.
pub fn tile_flags(a: &Args, manifest: &crate::one_world::Manifest) -> Vec<String> {
    use crate::args::GenerationMode;
    let flag = |name: &str, on: bool| format!("--{name}={on}");
    // The world fixed flat or real ground with its first area.
    let mode = match (a.mode.terrain(), manifest.terrain) {
        (have, want) if have == want => a.mode,
        (_, true) => GenerationMode::GeoTerrain,
        (_, false) => GenerationMode::GeoOnly,
    };
    let mut f = vec![
        "--live-tile".to_string(),
        "--map-item=false".to_string(),
        format!("--scale={}", manifest.scale),
        format!("--ground-level={}", manifest.ground_level),
        format!("--mode={}", value_name(&mode)),
        flag("winter", a.winter),
        flag("post-apocalyptic", a.post_apocalyptic),
        flag("interior", a.interior),
        flag("canopy-height", a.canopy_height),
        flag("overture", a.overture),
        format!("--overture-source={}", value_name(&a.overture_source)),
        format!("--fields={}", value_name(&a.fields)),
        format!("--max-tree-size={}", value_name(&a.max_tree_size)),
        format!("--signage={}", value_name(&a.signage)),
        format!("--osm-tiles-url={}", a.osm_tiles_url),
    ];
    if manifest.height_multiplier != 1.0 {
        f.push(format!(
            "--height-multiplier={}",
            manifest.height_multiplier
        ));
    }
    for (on, name) in [
        (a.fillground, "--fillground"),
        (a.caves, "--caves"),
        (a.legacy_trees, "--legacy-trees"),
        (!a.use_3d, "--no-3d"),
        (a.no_tile_archive, "--no-tile-archive"),
        (manifest.aws_only_elevation, "--aws-only-elevation"),
        (a.bake_lighting, "--bake-lighting"),
    ] {
        if on {
            f.push(name.to_string());
        }
    }
    if let Some(dir) = &a.cave_asset_pack {
        f.push(format!("--cave-asset-pack={}", dir.display()));
    }
    if let Some(list) = &a.cave_biomes {
        f.push(format!("--cave-biomes={list}"));
    }
    if let Some(on) = a.mapillary_facades {
        f.push(flag("mapillary-facades", on));
    }
    f.push(format!(
        "--mapillary-facade-mode={}",
        value_name(&a.mapillary_facade_mode)
    ));
    if let Some(dir) = &a.mapillary_facades_dir {
        f.push(format!("--mapillary-facades-dir={}", dir.display()));
    }
    if let Some(t) = a.timeout {
        f.push(format!("--timeout={}", t.as_secs().max(1)));
    }
    f
}

/// Settings a tile takes from its environment: the Mapillary token stays out of the
/// command line, where other programs could read it.
pub fn tile_env(a: &Args) -> Vec<(String, String)> {
    a.mapillary_token
        .as_deref()
        .map(str::trim)
        .filter(|t| !t.is_empty())
        .map(|t| vec![("MAPILLARY_TOKEN".to_string(), t.to_string())])
        .unwrap_or_default()
}

/// The block rectangle of region `(rx, rz)` and the lat/lon box that snaps to exactly it.
pub fn region_bbox(
    proj: &crate::projection::WebMercatorProjection,
    rx: i32,
    rz: i32,
) -> Result<(XZBBox, LLBBox), String> {
    let rect = XZBBox::rect_from_min_max(rx * 512, rz * 512, rx * 512 + 511, rz * 512 + 511)?;
    let ll = crate::projection::llbbox_for_rect(proj, &rect)?;
    let (snapped, _) = crate::projection::snap_bbox_to_chunks(proj, &ll)?;
    let same = (
        snapped.min_x(),
        snapped.min_z(),
        snapped.max_x(),
        snapped.max_z(),
    ) == (rect.min_x(), rect.min_z(), rect.max_x(), rect.max_z());
    if !same {
        return Err(format!("region {rx},{rz} does not map onto the world grid"));
    }
    if ll.min().lat() < -85.0 || ll.max().lat() > 85.0 {
        return Err("past the latitudes One World covers".to_string());
    }
    Ok((rect, ll))
}

pub fn live_root(world_dir: &Path) -> PathBuf {
    world_dir.join(LIVE_DIR)
}

pub fn staging_name(index: usize) -> String {
    format!("staging-{index}")
}

/// A fresh staging world: the live world's level.dat, manifest and build-height pack,
/// with its own block of map ids starting at `first_map_id`.
pub fn prepare_staging(
    world_dir: &Path,
    index: usize,
    first_map_id: i32,
) -> Result<PathBuf, String> {
    let dir = live_root(world_dir).join(staging_name(index));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).map_err(|e| format!("Failed to create {}: {e}", dir.display()))?;
    for file in ["level.dat", crate::one_world::MANIFEST_FILE] {
        fs::copy(world_dir.join(file), dir.join(file))
            .map_err(|e| format!("Failed to copy {file} into the staging world: {e}"))?;
    }
    let tall = world_dir
        .join("datapacks")
        .join(crate::world_utils::TALL_DATAPACK_NAME);
    if tall.is_dir() {
        copy_dir(
            &tall,
            &dir.join("datapacks")
                .join(crate::world_utils::TALL_DATAPACK_NAME),
        )?;
    }
    crate::map_item::set_map_counter(&dir, first_map_id - 1)?;
    Ok(dir)
}

/// First map id of staging world `index`, given the next free one in the live world.
pub fn first_map_id(live_next: i32, index: usize) -> i32 {
    live_next
        .saturating_add(10_000)
        .saturating_add(MAP_IDS_PER_WORKER.saturating_mul(index as i32))
}

fn copy_dir(src: &Path, dst: &Path) -> Result<(), String> {
    fs::create_dir_all(dst).map_err(|e| e.to_string())?;
    for entry in fs::read_dir(src).map_err(|e| e.to_string())? {
        let entry = entry.map_err(|e| e.to_string())?;
        let to = dst.join(entry.file_name());
        if entry.file_type().map_err(|e| e.to_string())?.is_dir() {
            copy_dir(&entry.path(), &to)?;
        } else {
            fs::copy(entry.path(), to).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

/// Map id of a map file, in either layout's naming.
pub fn map_id_of(name: &str) -> Option<i32> {
    let stem = name.strip_suffix(".dat")?;
    stem.strip_prefix("map_").unwrap_or(stem).parse().ok()
}

pub fn map_file_name(layout: WorldLayout, id: i32) -> String {
    match layout {
        WorldLayout::Legacy => format!("map_{id}.dat"),
        WorldLayout::Dimensions => format!("{id}.dat"),
    }
}

/// What a finished tile left in its staging world.
#[derive(Debug)]
pub struct Staged {
    pub region: PathBuf,
    pub maps: Vec<(i32, PathBuf)>,
    pub preview: Option<PathBuf>,
}

fn collect(staging: &Path, rx: i32, rz: i32) -> Result<Staged, String> {
    let layout = WorldLayout::of(staging);
    let region = layout
        .overworld_dir(staging)
        .join("region")
        .join(format!("r.{rx}.{rz}.mca"));
    if !region.is_file() {
        return Err("the tile wrote no region".to_string());
    }
    let mut maps = Vec::new();
    if let Ok(entries) = fs::read_dir(layout.maps_dir(staging)) {
        for e in entries.flatten() {
            let name = e.file_name().to_string_lossy().into_owned();
            if let Some(id) = map_id_of(&name) {
                maps.push((id, e.path()));
            }
        }
    }
    let preview = crate::one_world::Manifest::load(staging)
        .ok()
        .flatten()
        .and_then(|m| m.areas.last().and_then(|a| a.preview.clone()))
        .and_then(|rel| crate::one_world::safe_preview_path(staging, &rel))
        .filter(|p| p.is_file());
    Ok(Staged {
        region,
        maps,
        preview,
    })
}

pub struct Job {
    pub rx: i32,
    pub rz: i32,
    pub bbox: LLBBox,
}

pub struct Done {
    pub rx: i32,
    pub rz: i32,
    pub worker: usize,
    pub result: Result<Staged, String>,
    pub secs: f64,
}

/// Staging worlds and the processes generating into them.
pub struct Workers {
    jobs: Vec<Sender<Job>>,
    busy: Vec<Option<(i32, i32)>>,
    done: Receiver<Done>,
    children: Vec<Arc<Mutex<Option<Child>>>>,
}

impl Workers {
    pub fn new(
        world_dir: &Path,
        count: usize,
        flags: Vec<String>,
        env: Vec<(String, String)>,
        live_next_map: i32,
    ) -> Result<Self, String> {
        let exe =
            std::env::current_exe().map_err(|e| format!("Cannot find the arnis program: {e}"))?;
        let threads =
            (std::thread::available_parallelism().map_or(4, |n| n.get()) * 4 / 5 / count).max(2);
        let (done_tx, done) = channel();
        let mut jobs = Vec::new();
        let mut children = Vec::new();
        for index in 0..count {
            let staging = prepare_staging(world_dir, index, first_map_id(live_next_map, index))?;
            let (tx, rx) = channel::<Job>();
            let child: Arc<Mutex<Option<Child>>> = Arc::new(Mutex::new(None));
            let ctx = WorkerCtx {
                exe: exe.clone(),
                staging,
                output_dir: live_root(world_dir),
                name: staging_name(index),
                flags: flags.clone(),
                env: env.clone(),
                threads,
                child: child.clone(),
            };
            let done_tx = done_tx.clone();
            std::thread::spawn(move || {
                for job in rx {
                    let start = Instant::now();
                    let result = ctx.run(&job);
                    let sent = done_tx.send(Done {
                        rx: job.rx,
                        rz: job.rz,
                        worker: index,
                        result,
                        secs: start.elapsed().as_secs_f64(),
                    });
                    if sent.is_err() {
                        break;
                    }
                }
            });
            jobs.push(tx);
            children.push(child);
        }
        Ok(Self {
            busy: vec![None; jobs.len()],
            jobs,
            done,
            children,
        })
    }

    pub fn idle(&self) -> Option<usize> {
        self.busy.iter().position(Option::is_none)
    }

    pub fn running(&self) -> usize {
        self.busy.iter().filter(|b| b.is_some()).count()
    }

    pub fn is_running(&self, region: (i32, i32)) -> bool {
        self.busy.contains(&Some(region))
    }

    pub fn dispatch(&mut self, worker: usize, job: Job) {
        self.busy[worker] = Some((job.rx, job.rz));
        let _ = self.jobs[worker].send(job);
    }

    /// A finished tile. Its worker stays busy until `release`, so the staging world is not
    /// written again before the tile's files have been moved out.
    pub fn try_recv(&mut self) -> Option<Done> {
        self.done.try_recv().ok()
    }

    pub fn wait_recv(&mut self, timeout: std::time::Duration) -> Option<Done> {
        self.done.recv_timeout(timeout).ok()
    }

    pub fn release(&mut self, worker: usize) {
        self.busy[worker] = None;
    }

    pub fn kill_all(&self) {
        for c in &self.children {
            if let Some(child) = c.lock().unwrap_or_else(|e| e.into_inner()).as_mut() {
                let _ = child.kill();
            }
        }
    }
}

struct WorkerCtx {
    exe: PathBuf,
    staging: PathBuf,
    output_dir: PathBuf,
    name: String,
    flags: Vec<String>,
    env: Vec<(String, String)>,
    threads: usize,
    child: Arc<Mutex<Option<Child>>>,
}

impl WorkerCtx {
    fn run(&self, job: &Job) -> Result<Staged, String> {
        let log_path = self.staging.join("tile.log");
        let log = fs::File::create(&log_path).map_err(|e| e.to_string())?;
        let mut cmd = Command::new(&self.exe);
        cmd.arg("--one-world")
            .arg(format!("--output-dir={}", self.output_dir.display()))
            .arg(format!("--world-name={}", self.name))
            .arg(format!(
                "--bbox={},{},{},{}",
                job.bbox.min().lat(),
                job.bbox.min().lng(),
                job.bbox.max().lat(),
                job.bbox.max().lng()
            ))
            .args(&self.flags)
            .envs(self.env.iter().map(|(k, v)| (k, v)))
            .env("RAYON_NUM_THREADS", self.threads.to_string())
            .stdin(Stdio::null())
            .stdout(log.try_clone().map_err(|e| e.to_string())?)
            .stderr(log);
        super::server::detach(&mut cmd);
        let started = Instant::now();
        let spawned = cmd
            .spawn()
            .map_err(|e| format!("Could not start a tile: {e}"))?;
        *self.child.lock().unwrap_or_else(|e| e.into_inner()) = Some(spawned);
        let status = loop {
            let mut guard = self.child.lock().unwrap_or_else(|e| e.into_inner());
            let Some(child) = guard.as_mut() else {
                return Err("cancelled".to_string());
            };
            match child.try_wait() {
                Ok(Some(status)) => {
                    *guard = None;
                    break status;
                }
                Ok(None) if started.elapsed() > TILE_DEADLINE => {
                    let _ = child.kill();
                    let _ = child.wait();
                    *guard = None;
                    return Err("the tile took too long".to_string());
                }
                Ok(None) => {}
                Err(e) => return Err(e.to_string()),
            }
            drop(guard);
            std::thread::sleep(std::time::Duration::from_millis(100));
        };
        if !status.success() {
            return Err(
                last_error(&log_path).unwrap_or_else(|| format!("the tile failed ({status})"))
            );
        }
        collect(&self.staging, job.rx, job.rz)
    }
}

/// The last error line a tile printed, for the status line.
fn last_error(log: &Path) -> Option<String> {
    let text = fs::read_to_string(log).ok()?;
    text.lines()
        .rev()
        .find(|l| l.contains("Error"))
        .map(|l| l.trim().trim_start_matches("Error:").trim().to_string())
        .filter(|l| !l.is_empty())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::projection::WebMercatorProjection;
    use clap::Parser;

    #[test]
    fn region_boxes_snap_back_to_the_region() {
        let proj = WebMercatorProjection::new(52.5163, 13.3777, 1.0);
        for (rx, rz) in [(0, 0), (-1, -1), (37, -12), (-250, 410), (1500, -900)] {
            let (rect, ll) = region_bbox(&proj, rx, rz).unwrap();
            assert_eq!((rect.min_x(), rect.min_z()), (rx * 512, rz * 512));
            // The box goes through --bbox as text, so check that round trip too.
            let text = format!(
                "{},{},{},{}",
                ll.min().lat(),
                ll.min().lng(),
                ll.max().lat(),
                ll.max().lng()
            );
            let parsed = LLBBox::from_str(&text).unwrap();
            let (snapped, _) = crate::projection::snap_bbox_to_chunks(&proj, &parsed).unwrap();
            assert_eq!(
                (
                    snapped.min_x(),
                    snapped.min_z(),
                    snapped.max_x(),
                    snapped.max_z()
                ),
                (rect.min_x(), rect.min_z(), rect.max_x(), rect.max_z()),
                "region {rx},{rz}"
            );
        }
    }

    #[test]
    fn tile_flags_parse_back() {
        let args = Args::parse_from([
            "arnis",
            "--one-world",
            "--bbox",
            "52.5,13.3,52.51,13.31",
            "--winter",
            "--caves",
            "--signage=full",
            "--mode=terrain-only",
            "--no-3d",
        ]);
        let manifest: crate::one_world::Manifest = serde_json::from_value(serde_json::json!({
            "version": 3, "created_with": "test", "created_at": 0, "origin_lat": 52.5,
            "origin_lon": 13.3, "scale": 1.5, "ground_level": -62, "terrain": true,
            "disable_height_limit": true, "aws_only_elevation": false, "elevation": null,
            "next_area_id": 1, "areas": []
        }))
        .unwrap();
        let mut argv = vec![
            "arnis".to_string(),
            "--one-world".to_string(),
            "--bbox=1,2,3,4".to_string(),
        ];
        argv.extend(tile_flags(&args, &manifest));
        let back = Args::try_parse_from(argv).unwrap();
        assert!(back.winter && back.caves && !back.use_3d && back.live.tile && !back.map_item);
        assert_eq!(back.scale, 1.5);
        assert_eq!(back.signage, crate::args::SignageLevel::Full);
        assert_eq!(back.mode, crate::args::GenerationMode::TerrainOnly);

        // A flat world keeps flat tiles, whatever the settings say now.
        let mut flat = manifest;
        flat.terrain = false;
        let mut argv = vec!["arnis".to_string(), "--bbox=1,2,3,4".to_string()];
        argv.extend(tile_flags(&args, &flat));
        let back = Args::try_parse_from(argv).unwrap();
        assert_eq!(back.mode, crate::args::GenerationMode::GeoOnly);
    }

    #[test]
    fn the_mapillary_token_goes_through_the_environment() {
        let args = Args::parse_from([
            "arnis",
            "--bbox",
            "52.5,13.3,52.51,13.31",
            "--mapillary-token=abc",
        ]);
        assert_eq!(
            tile_env(&args),
            vec![("MAPILLARY_TOKEN".to_string(), "abc".to_string())]
        );
    }

    #[test]
    fn map_names_are_read_in_both_layouts() {
        assert_eq!(map_id_of("map_1000042.dat"), Some(1_000_042));
        assert_eq!(map_id_of("1000042.dat"), Some(1_000_042));
        assert_eq!(map_id_of("idcounts.dat"), None);
        assert_eq!(map_id_of("last_id.dat"), None);
        assert_eq!(map_file_name(WorldLayout::Legacy, 7), "map_7.dat");
        assert_eq!(map_file_name(WorldLayout::Dimensions, 7), "7.dat");
    }
}
